// CADASTRO UNICO DAS 47 PLACAS. Use MAC real em MAIUSCULAS.
const salas = {};
const d = msg.payload;
const mac = d && typeof d.dispositivo === "string" ? d.dispositivo.trim().toUpperCase() : "";
if (!/^([0-9A-F]{2}:){5}[0-9A-F]{2}$/.test(mac) || mac === "00:00:00:00:00:00" || mac === "FF:FF:FF:FF:FF:FF") {
    msg.statusCode = 400;
    msg.payload = {ok:false, erro:"Identificador de placa invalido."};
} else if (!Object.prototype.hasOwnProperty.call(salas, mac)) {
    node.warn("Cadastre esta placa: " + mac);
    msg.statusCode = 404;
    msg.payload = {ok:false, erro:"Placa sem sala cadastrada: " + mac};
} else if (typeof salas[mac] !== "string" || !salas[mac].trim() || salas[mac].length > 80) {
    msg.statusCode = 500;
    msg.payload = {ok:false, erro:"Corrija o nome da sala no cadastro."};
} else {
    msg.dispositivo = mac;
    msg.sala = salas[mac].trim();
    return [msg, null];
}
msg.headers = {"Content-Type":"application/json; charset=utf-8", "Cache-Control":"no-store"};
return [null, msg];

const tipos = ["pedagogico", "limpeza", "infraestrutura"];
const nomes = {pedagogico:"Orientação Pedagógica", limpeza:"Limpeza", infraestrutura:"Infraestrutura"};
function erro(codigo, texto) {
    msg.statusCode = codigo;
    msg.headers = {"Content-Type":"application/json; charset=utf-8", "Cache-Control":"no-store"};
    msg.payload = {ok:false, erro:texto};
    return [msg, null];
}
const estados = msg.payload && msg.payload.estados;
if (!Array.isArray(estados) || estados.length !== 3) return erro(400,"Envie os tres estados.");
const vistos = new Set();
for (const e of estados) {
    if (!e || !tipos.includes(e.tipo) || vistos.has(e.tipo)
        || typeof e.ativo !== "boolean" || !Number.isInteger(e.revisao)
        || e.revisao < 0 || e.revisao > 4294967295
        || e.ativo !== (e.revisao % 2 === 1)) {
        return erro(400,"Estado, tipo ou revisao invalida.");
    }
    vistos.add(e.tipo);
}
let db;
try {
    // Evita usar memoria por engano quando o store arquivo nao foi configurado.
    if (flow.get("__verificarV3", "arquivo") !== "ARQUIVO_V3") {
        flow.set("__verificarV3", "ARQUIVO_V3", "arquivo");
    }
    if (flow.get("__verificarV3", "memoria") === "ARQUIVO_V3") {
        throw new Error("Configure os stores memoria e arquivo conforme o guia.");
    }
    const salvo = flow.get("pedidosV3", "arquivo");
    db = salvo ? JSON.parse(JSON.stringify(salvo)) : {versao:3, estados:{}, pedidos:{}};
} catch (_) {
    return erro(503,"Configure contextStorage arquivo no settings.js e reinicie o Node-RED.");
}
if (db.versao !== 3 || !db.estados || !db.pedidos) return erro(500,"Armazenamento incompativel; restaure um backup.");
// Valida todas as revisoes antes de alterar qualquer pedido.
for (const e of estados) {
    const anterior = db.estados[msg.dispositivo + "|" + e.tipo];
    if (anterior && e.revisao < anterior.revisao) return erro(409,"Revisao antiga. Verifique se a memoria da placa foi apagada.");
}
const agora = new Date().toISOString();
let alterou = false;
const notificacoes = [];
for (const e of estados) {
    const chave = msg.dispositivo + "|" + e.tipo;
    const anterior = db.estados[chave];
    if (anterior && e.revisao === anterior.revisao) continue;
    alterou = true;
    const anteriorRev = anterior ? anterior.revisao : 0;
    const parcial = e.revisao > anteriorRev + 1;
    const revisaoAbertura = e.ativo ? e.revisao : e.revisao - 1;
    const pedidoId = e.revisao > 0 ? chave + "|" + revisaoAbertura : null;
    // Fecha ciclo anterior se houve varios toques sem comunicacao.
    if (anterior && anterior.pedidoId && anterior.pedidoId !== pedidoId) {
        const antigo = db.pedidos[anterior.pedidoId];
        if (antigo && antigo.ativo) {
            antigo.ativo = false;
            antigo.encerradoEm = agora;
            antigo.motivo = "Encerrado pelo botão (sincronizado após interrupção)";
            antigo.registroParcial = true;
        }
    }
    if (pedidoId) {
        let pedido = db.pedidos[pedidoId];
        if (!pedido) {
            pedido = {
                id:pedidoId, dispositivo:msg.dispositivo, sala:msg.sala,
                tipo:e.tipo, servico:nomes[e.tipo], ativo:e.ativo,
                abertoEm:e.ativo ? agora : null, recebidoEm:agora,
                encerradoEm:e.ativo ? null : agora,
                motivo:e.ativo ? null : "Encerrado pelo botão",
                registroParcial:parcial || !e.ativo
            };
            db.pedidos[pedidoId] = pedido;
        } else if (!e.ativo) {
            pedido.ativo = false;
            pedido.encerradoEm = agora;
            pedido.motivo = "Encerrado pelo botão";
            pedido.registroParcial = pedido.registroParcial || parcial;
        }
        notificacoes.push({payload:{
            text:(e.ativo ? "🔔 PEDIDO RECEBIDO" : "✅ PEDIDO ENCERRADO PELO BOTÃO")
                + "\nLocal: " + msg.sala + "\nServiço: " + nomes[e.tipo]
                + (parcial ? "\nEstado atualizado após intervalo de comunicação." : "")
        }});
    }
    db.estados[chave] = {revisao:e.revisao, ativo:e.ativo, pedidoId, sala:msg.sala};
}
if (alterou) {
    try { flow.set("pedidosV3", db, "arquivo"); }
    catch (_) { return erro(503,"Nao foi possivel salvar os pedidos."); }
}
msg.statusCode = 200;
msg.headers = {"Content-Type":"text/plain; charset=utf-8", "Cache-Control":"no-store"};
msg.payload = "BOTOES_MAGICOS_SYNC_OK";
return [msg, notificacoes.length ? notificacoes : null];

// OPCIONAL: o painel funciona mesmo sem Telegram.
const botToken = "COLE_SEU_TOKEN_AQUI";
const chatId = "COLE_SEU_CHAT_ID_AQUI";
if (botToken === "COLE_SEU_TOKEN_AQUI" || chatId === "COLE_SEU_CHAT_ID_AQUI") return null;
msg.url = "https://api.telegram.org/bot" + botToken + "/sendMessage";
msg.method = "POST";
msg.headers = {"Content-Type":"application/json"};
msg.requestTimeout = 10000;
msg.payload = {chat_id:chatId, text:msg.payload.text};
return msg;

if (Number(msg.statusCode) !== 200 || !msg.payload || msg.payload.ok !== true) {
    node.warn("Telegram nao confirmou a notificacao. O pedido permanece registrado no painel.");
}
return null;

try {
    // Evita usar memoria por engano quando o store arquivo nao foi configurado.
    if (flow.get("__verificarV3", "arquivo") !== "ARQUIVO_V3") {
        flow.set("__verificarV3", "ARQUIVO_V3", "arquivo");
    }
    if (flow.get("__verificarV3", "memoria") === "ARQUIVO_V3") {
        throw new Error("Configure os stores memoria e arquivo conforme o guia.");
    }
    flow.get("pedidosV3", "arquivo");
    msg.statusCode = 200;
    msg.payload = "BOTOES_MAGICOS_OK";
} catch (_) {
    msg.statusCode = 503;
    msg.payload = "Configure contextStorage arquivo no Node-RED.";
}
msg.headers = {"Content-Type":"text/plain; charset=utf-8", "Cache-Control":"no-store"};
return msg;

try {
    // Evita usar memoria por engano quando o store arquivo nao foi configurado.
    if (flow.get("__verificarV3", "arquivo") !== "ARQUIVO_V3") {
        flow.set("__verificarV3", "ARQUIVO_V3", "arquivo");
    }
    if (flow.get("__verificarV3", "memoria") === "ARQUIVO_V3") {
        throw new Error("Configure os stores memoria e arquivo conforme o guia.");
    }
    const db = flow.get("pedidosV3", "arquivo") || {pedidos:{}};
    const todos = Object.values(db.pedidos);
    msg.statusCode = 200;
    msg.payload = {
        ok:true, atualizadoEm:new Date().toISOString(),
        recebidos:todos.filter(p=>p.ativo).sort((a,b)=>b.recebidoEm.localeCompare(a.recebidoEm)),
        feitos:todos.filter(p=>!p.ativo).sort((a,b)=>b.encerradoEm.localeCompare(a.encerradoEm))
    };
} catch (_) {
    msg.statusCode = 503;
    msg.payload = {ok:false, erro:"Configure contextStorage arquivo no settings.js e reinicie o Node-RED."};
}
msg.headers = {"Content-Type":"application/json; charset=utf-8", "Cache-Control":"no-store"};
return msg;
